// Recorded synthetic service responses. No network, provider, or real authenticator is used here.
private enum WithdrawalFixtureData {
    static let bytes = Data(base64Encoded: "")!
    static var value: [String: Any] { try! JSONSerialization.jsonObject(with: bytes) as! [String: Any] }
    static func data(_ key: String) -> Data { try! JSONSerialization.data(withJSONObject: value[key]!) }
}
private struct WithdrawalFixtureVault: MemberSessionVault {
    let info: MemberSessionInfo
    func load(environment: MemberEnvironment, household: String) throws -> StoredMemberSession? {
        let object: [String: Any] = ["token": "amr1_" + String(repeating: "A", count: 43), "info": try JSONSerialization.jsonObject(with: JSONEncoder().encode(info))]
        return try JSONDecoder().decode(StoredMemberSession.self, from: JSONSerialization.data(withJSONObject: object))
    }
    func save(_ session: StoredMemberSession, environment: MemberEnvironment) throws {}
    func remove(environment: MemberEnvironment, household: String) throws {}
}
private actor WithdrawalFixtureTransport: MemberHTTPTransport {
    var submitted = false
    func send(_ request: URLRequest) async throws -> MemberHTTPReply {
        let path = request.url!.path
        let bytes: Data
        if path == "/auth/session" { bytes = WithdrawalFixtureData.data("session") }
        else if path.hasSuffix("/submit") { submitted = true; throw URLError(.networkConnectionLost) }
        else if path == "/member/decisions/prepare" { bytes = WithdrawalFixtureData.data("decisionPrepared") }
        else if path == "/member/operations/" + ((WithdrawalFixtureData.value["decisionPrepared"] as! [String: Any])["operationID"] as! String) + "/outcome" { bytes = WithdrawalFixtureData.data("decisionOutcome") }
        else if path == "/member/operations/" + ((WithdrawalFixtureData.value["decisionPrepared"] as! [String: Any])["operationID"] as! String) {
            var review = WithdrawalFixtureData.value["decisionPrepared"] as! [String: Any]; review["operationState"] = "committed"
            bytes = try JSONSerialization.data(withJSONObject: review)
        }
        else if path.hasSuffix("/outcome") && submitted { bytes = WithdrawalFixtureData.data("withdrawalOutcome") }
        else if path.hasSuffix("/cancel") { bytes = Data(#"{"cancelled":true}"#.utf8) }
        else { bytes = WithdrawalFixtureData.data("withdrawalPrepared") }
        return .init(url: request.url!, status: 200, contentType: "application/json", cacheControl: "no-store", data: bytes)
    }
}
@MainActor private final class WithdrawalFixturePasskeys: MemberPasskeyAuthorising {
    func authorise(_ ceremony: MemberCeremony, kind: NativePasskeyOptions.Kind) async throws -> MemberPasskeyResponse {
        guard kind == .withdrawal, case .string(let challenge) = ceremony.publicKey["challenge"],
              case .array(let allowed) = ceremony.publicKey["allowCredentials"], case .object(let credential) = allowed[0], case .string(let id) = credential["id"] else { throw NativePasskeyFailure.invalidOptions }
        let data = try JSONSerialization.data(withJSONObject: ["type":"webauthn.get", "origin":"https://unit.example", "challenge":challenge])
        let encoded = data.base64EncodedString().replacingOccurrences(of: "+", with: "-").replacingOccurrences(of: "/", with: "_").replacingOccurrences(of: "=", with: "")
        return .assertion(id: id, clientDataJSON: encoded, authenticatorData: "YQ", signature: "YQ", userHandle: "YQ")
    }
}
@MainActor private final class WithdrawalFixtureModel: ObservableObject {
    let flow: MemberWithdrawalFlow
    let client: MemberClient
    let session: MemberSessionInfo
    let local: PreparedMemberDecision
    let store: FileMemberOperationStore
    @Published var original: MemberOperationHandle?
    init() {
        session = try! JSONDecoder().decode(MemberSessionInfo.self, from: WithdrawalFixtureData.data("session"))
        var raw = (WithdrawalFixtureData.value["decisionOutcome"] as! [String: Any])["decision"] as! [String: Any]
        raw.removeValue(forKey: "reminders_sent"); raw["state"] = "presented"; raw["decided_at"] = NSNull()
        raw["candidates"] = (raw["candidates"] as! [[String: Any]]).map { c in
            var c = c; c["valence"] = "offered"; c["decided_at"] = NSNull(); c["kept_as"] = NSNull(); c["lineage"] = NSNull(); return c
        }
        let detail = try! MemberOfferDetail.decode(JSONSerialization.data(withJSONObject: raw), expectedID: raw["id"] as! String, household: session.household)
        let view = (WithdrawalFixtureData.value["decisionPrepared"] as! [String: Any])["review"] as! [String: Any]
        let approval = try! MemberApproval.decode(JSONSerialization.data(withJSONObject: view["approval"]!), detail: detail)
        var choices = MemberDigitalDraft(approval: approval)
        for candidate in approval.candidates { try! choices.choose(.keep, candidate: candidate.id) }
        let environment = try! MemberEnvironment(name: "test", origin: URL(string: "https://unit.example")!)
        local = try! PreparedMemberDecision(environment: environment, session: session, detail: detail, draft: choices, now: 1_800_000_000_001)
        client = MemberClient(environment: environment, transport: WithdrawalFixtureTransport(), vault: WithdrawalFixtureVault(info: session), now: { 1_800_000_000_001 })
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("withdrawal-ui-fixture")
        if ProcessInfo.processInfo.arguments.contains("--fresh") { try? FileManager.default.removeItem(at: directory) }
        store = try! FileMemberOperationStore(directory: directory)
        flow = MemberWithdrawalFlow(environment: environment, service: client, passkeys: WithdrawalFixturePasskeys(), store: store, now: { 1_800_000_000_001 })
    }
    func start() async {
        _ = try? await client.restore(household: session.household)
        flow.setSession(session)
        original = try? await client.prepareDecision(local, store: store).0
    }
}
